import torch
import torch.nn as nn
import torch.nn.functional as F
from typing import Union

def round_ste(x: torch.Tensor):
    return (x.round() - x).detach() + x

def lp_loss(pred, tgt, p=2.0, reduction='none'):
    if reduction == 'none':
        return (pred - tgt).abs().pow(p).sum(1).mean()
    else:
        return (pred - tgt).abs().pow(p).mean()

class UniformAffineQuantizer(nn.Module):
    def __init__(self, n_bits: int = 8, symmetric: bool = False, channel_wise: bool = False, scale_method: str = 'minmax', leaf_param: bool = False, prob: float = 1.0,):
        super().__init__()
        self.n_bits = n_bits
        self.n_levels = 2**self.n_bits
        self.delta = 1.0
        self.zero_point = 0.0
        self.inited = False
        self.scale_method = scale_method # e.g., 'mse'
        self.num = 100 # For search iterations in MSE
        self.timewise_quant_mode = False
        self.timestep_params = {}
        self.sym = symmetric
        self.one_side_dist = None

    def change_timestep(self, t):
        assert self.timewise_quant_mode
        if self.now_t is not None: self.timestep_params[self.now_t] = [self.delta, self.zero_point, self.inited]
        if t not in self.timestep_params: self.timestep_params[t] = [1, 0, False]
        self.delta, self.zero_point, self.inited = self.timestep_params[t]
        self.now_t = t

    def forward(self, x: torch.Tensor):
        if not self.inited: self.delta, self.zero_point = self.init_quantization_scale(x.clone().detach(), self.channel_wise); self.inited = True
        x_int = round_ste(x / self.delta) + self.zero_point
        x_quant = torch.clamp(x_int, 0, self.n_levels - 1)
        return (x_quant - self.zero_point) * self.delta

    def calculate_qparams(self, min_val, max_val):
        quant_min, quant_max = 0, self.n_levels - 1
        min_val_neg = torch.min(min_val, torch.zeros_like(min_val))
        max_val_pos = torch.max(max_val, torch.zeros_like(max_val))
        scale = (max_val_pos - min_val_neg) / float(quant_max - quant_min)
        zero_point = quant_min - torch.round(min_val_neg / scale)
        zero_point = torch.clamp(zero_point, quant_min, quant_max)
        return scale, zero_point

    def perform_1D_search(self, x): # Representative of MSE search, simplified to symmetric
        x_min, x_max = torch._aminmax(x)
        xrange = torch.max(x_min.abs(), x_max)
        best_score = torch.zeros_like(x_min) + (1e10)
        best_min = x_min.clone(); best_max = x_max.clone()
        for i in range(1, self.num + 1):
            thres = xrange / self.num * i; new_min, new_max = -thres, thres # Symmetric for simplicity
            # self.quantize is a helper using calculate_qparams for actual quantization logic
            x_q = self.quantize(x, new_max, new_min) # Assuming self.quantize exists
            score = lp_loss(x, x_q, 2.4)
            best_min = torch.where(score < best_score, new_min, best_min)
            best_max = torch.where(score < best_score, new_max, best_max)
            best_score = torch.min(score, best_score)
        return best_min, best_max

    def init_quantization_scale(self, x_clone: torch.Tensor, channel_wise: bool = False):
        # In full code, logic chooses between 1D/2D search based on distribution
        # Here, demonstrating 1D search for brevity.
        x_min, x_max = self.perform_1D_search(x_clone) 
        return self.calculate_qparams(x_min, x_max)


class StraightThrough(nn.Module):
    def forward(self, input): return input

class QuantModule(nn.Module):
    def __init__(self, org_module: Union[nn.Conv2d, nn.Linear], weight_quant_params: dict = {}, act_quant_params: dict = {}, disable_act_quant=False,):
        super().__init__()
        self.fwd_func = F.conv2d if isinstance(org_module, nn.Conv2d) else F.linear
        self.fwd_kwargs = dict(stride=org_module.stride, padding=org_module.padding, dilation=org_module.dilation, groups=org_module.groups) if isinstance(org_module, nn.Conv2d) else dict()
        self.weight = org_module.weight; self.org_weight = org_module.weight.data.clone()
        self.bias = org_module.bias; self.org_bias = org_module.bias.data.clone() if org_module.bias is not None else None
        self.use_weight_quant = False; self.use_act_quant = False
        self.weight_quantizer = UniformAffineQuantizer(**weight_quant_params)
        self.act_quantizer = UniformAffineQuantizer(**act_quant_params)
        self.activation_function = StraightThrough()
        self.disable_act_quant = disable_act_quant

    def forward(self, input: torch.Tensor):
        weight = self.weight_quantizer(self.weight) if self.use_weight_quant else self.org_weight
        bias = self.bias if self.use_weight_quant else self.org_bias
        out = self.fwd_func(input, weight, bias, **self.fwd_kwargs)
        out = self.activation_function(out)
        if self.disable_act_quant: return out
        if self.use_act_quant: out = self.act_quantizer(out)
        return out

class AdaRoundQuantizer(nn.Module):
    def __init__(self, uaq: UniformAffineQuantizer, weight_tensor: torch.Tensor, round_mode='learned_round_sigmoid'):
        super().__init__()
        self.n_bits = uaq.n_bits; self.delta = uaq.delta; self.zero_point = uaq.zero_point; self.n_levels = uaq.n_levels
        self.round_mode = round_mode; self.alpha = None; self.soft_targets = False
        self.gamma, self.zeta = -0.1, 1.1
        self.init_alpha(x=weight_tensor.clone())

    def forward(self, x):
        x_floor = torch.floor(x / self.delta)
        if self.soft_targets: x_int = x_floor + self.get_soft_targets()
        else: x_int = x_floor + (self.alpha >= 0).float()
        x_quant = torch.clamp(x_int + self.zero_point, 0, self.n_levels - 1)
        return (x_quant - self.zero_point) * self.delta

    def get_soft_targets(self): return torch.clamp(torch.sigmoid(self.alpha) * (self.zeta - self.gamma) + self.gamma, 0, 1)

    def init_alpha(self, x: torch.Tensor):
        x_floor = torch.floor(x / self.delta); rest = (x / self.delta) - x_floor
        alpha = -torch.log((self.zeta - self.gamma) / (rest - self.gamma) - 1)
        self.alpha = nn.Parameter(alpha)


class LinearTempDecay:
    def __init__(self, t_max: int, rel_start_decay: float = 0.2, start_b: int = 10, end_b: int = 2):
        self.t_max = t_max; self.start_decay = rel_start_decay * t_max; self.start_b = start_b; self.end_b = end_b
    def __call__(self, t):
        if t < self.start_decay: return self.start_b
        else:
            rel_t = (t - self.start_decay) / (self.t_max - self.start_decay)
            return self.end_b + (self.start_b - self.end_b) * max(0.0, (1 - rel_t))


class LossFunction:
    def __init__(self, layer: Union[nn.Module], round_loss: str = 'relaxation', weight: float = 1., rec_loss: str = 'mse', max_count: int = 2000, b_range: tuple = (10, 2), warmup: float = 0.0, p: float = 2.):
        self.layer = layer; self.round_loss = round_loss; self.weight = weight; self.rec_loss = rec_loss
        self.loss_start = max_count * warmup; self.p = p; self.temp_decay = LinearTempDecay(max_count, warmup, b_range[0], b_range[1])
        self.count = 0
    def __call__(self, pred, tgt, grad=None):
        self.count += 1
        rec_loss = lp_loss(pred, tgt, p=self.p) if self.rec_loss == 'mse' else torch.tensor(0.0, device=pred.device)
        b = self.temp_decay(self.count); round_loss = torch.tensor(0.0, device=pred.device)
        if self.count >= self.loss_start and self.round_loss == 'relaxation':
            # Simplified: Assuming layer has a direct weight_quantizer for demo
            round_vals = self.layer.weight_quantizer.get_soft_targets()
            round_loss = self.weight * (1 - ((round_vals - .5).abs() * 2).pow(b)).sum()
        return rec_loss + round_loss

def layer_reconstruction(model_qnn, layer_qmodule, cali_data, iters, weight, b_range, warmup, opt_mode, act_quant, lr, input_prob, keep_gpu, wwq, waq, order):
    from QDrop.quant.set_weight_quantize_params import weight_get_quant_state, get_init
    from QDrop.quant.set_act_quantize_params import set_act_quantize_params

    cached_inps, cached_outs = get_init(model_qnn, layer_qmodule, cali_data, wq=wwq, aq=waq, input_prob=True, keep_gpu=keep_gpu)
    layer_qmodule.weight_quantizer = AdaRoundQuantizer(uaq=layer_qmodule.weight_quantizer, weight_tensor=layer_qmodule.org_weight.data)
    layer_qmodule.weight_quantizer.soft_targets = True
    w_para = [layer_qmodule.weight_quantizer.alpha]; w_opt = torch.optim.Adam(w_para)
    loss_func = LossFunction(layer_qmodule, weight=weight, max_count=iters, rec_loss=opt_mode, b_range=b_range, warmup=warmup)
    device = 'cuda'; sz = cached_inps[0].size(0)
    for i in range(iters):
        idx = torch.randint(0, sz, (32,)); cur_inp, cur_out = cached_inps[0][idx].to(device), cached_outs[idx].to(device)
        w_opt.zero_grad(); out_quant = layer_qmodule(cur_inp); err = loss_func(out_quant, cur_out); err.backward(retain_graph=True)
        w_opt.step()
    layer_qmodule.weight_quantizer.soft_targets = False


class QuantModel(nn.Module):
    def __init__(self, model: nn.Module, weight_quant_params: dict = {}, act_quant_params: dict = {},):
        super().__init__()
        self.model = model
        self.quant_module_refactor(self.model, weight_quant_params, act_quant_params)

    def quant_module_refactor(self, module: nn.Module, weight_quant_params: dict = {}, act_quant_params: dict = {},):
        for name, child_module in module.named_children():
            if isinstance(child_module, (nn.Conv2d, nn.Linear)): setattr(module, name, QuantModule(child_module, weight_quant_params, act_quant_params))
            elif isinstance(child_module, (nn.ReLU, nn.ReLU6)):
                # Correct assignment: actual activation function to QuantModule
                prev_quantmodule = getattr(module, name) if isinstance(getattr(module, name), QuantModule) else None
                if prev_quantmodule is not None: prev_quantmodule.activation_function = child_module
                setattr(module, name, StraightThrough()) # Replace original activation with passthrough
            else: self.quant_module_refactor(child_module, weight_quant_params, act_quant_params)

    def set_quant_state(self, weight_quant: bool = False, act_quant: bool = False):
        for m in self.model.modules():
            if isinstance(m, QuantModule): m.set_quant_state(weight_quant, act_quant)

    def disable_network_output_quantization(self):
        module_list = []; [module_list.append(m) for m in self.model.modules() if isinstance(m, QuantModule)]
        if module_list: module_list[-1].disable_act_quant = True

    def set_first_last_layer_to_8bit(self):
        w_list, a_list = [], []
        for module in self.model.modules():
            if isinstance(module, UniformAffineQuantizer):
                if module.leaf_param: a_list.append(module)
                else: w_list.append(module)
        if w_list: w_list[0].bitwidth_refactor(8); w_list[-1].bitwidth_refactor(8) # Assuming bitwidth_refactor exists
        if a_list and len(a_list) > 1: a_list[-2].bitwidth_refactor(8)


def generate_t(args, t_mode, num_samples, diffusion, device):
    if t_mode == 'normal':
        normal_val = torch.nn.init.normal_(torch.Tensor(num_samples), mean=args.calib_t_mode_normal_mean, std=args.calib_t_mode_normal_std) * diffusion.num_timesteps
        t = normal_val.clone().type(torch.int).to(device=device)
    else: t = torch.randint(0, diffusion.num_timesteps, [num_samples], device=device) # Simplified default for other modes
    return t.clamp(0, diffusion.num_timesteps - 1)


def forward_t_calib_data_generator(args, num_samples, device, t_mode, diffusion, class_cond=True):
    from improved_diffusion.image_datasets import load_data # placeholder for load_data
    loader = load_data(data_dir=args.data_dir, batch_size=num_samples, image_size=args.image_size, class_cond=class_cond)
    calib_data, cls_labels = next(loader)
    calib_data = calib_data.to(device)
    t = generate_t(args, t_mode, num_samples, diffusion, device).long()
    x_t = diffusion.q_sample(calib_data, t) # Denoising process to get calibration samples
    t_scaled = diffusion._scale_timesteps(t) # Scale time steps for model input
    if class_cond: return x_t, t_scaled, cls_labels.to(device)
    else: return x_t, t_scaled


