def quant_model(args, model, diffusion):
    from QDrop.quant import QuantModule, QuantModel, BaseQuantBlock
    from QDrop.quant.set_weight_quantize_params import set_weight_quantize_params
    from QDrop.quant.set_act_quantize_params import set_act_quantize_params
    from QDrop.quant.layer_recon import layer_reconstruction # Assuming layer_reconstruction is imported here

    wq_params = {'n_bits': args.n_bits_w, 'channel_wise': args.channel_wise, 'scale_method': args.init_wmode, 'symmetric': True}
    aq_params = {'n_bits': args.n_bits_a, 'channel_wise': False, 'scale_method': args.init_amode, 'leaf_param': True, 'prob': args.prob, 'symmetric': True}

    qnn = QuantModel(model=model, weight_quant_params=wq_params, act_quant_params=aq_params)
    qnn.cuda(); qnn.eval()
    if not args.disable_8bit_head_stem: qnn.set_first_last_layer_to_8bit()
    qnn.disable_network_output_quantization()

    cali_data = forward_t_calib_data_generator(args, args.calib_num_samples, 'cuda', args.calib_t_mode, diffusion, args.class_cond)

    kwargs = dict(cali_data=cali_data, iters=args.iters_w, weight=args.weight, b_range=(args.b_start, args.b_end), warmup=args.warmup, opt_mode='mse', wwq=True, waq=True, order='together', act_quant=args.act_quant, lr=args.lr, input_prob=args.input_prob, keep_gpu=False)

    if args.act_quant and args.order == 'before': set_act_quantize_params(qnn, cali_data=cali_data, awq=False, order=args.order)

    set_weight_quantize_params(qnn)

    if args.use_adaround:
        def set_weight_act_quantize_params(module):
            if isinstance(module, QuantModule): layer_reconstruction(qnn, module, **kwargs)
            # For BaseQuantBlock, block_reconstruction would be called. Simplified here.
            # elif isinstance(module, BaseQuantBlock): block_reconstruction(qnn, module, **kwargs)

        def recon_model_recursive(model_to_recon: nn.Module):
            for _, module_child in model_to_recon.named_children():
                if isinstance(module_child, (QuantModule, BaseQuantBlock)): set_weight_act_quantize_params(module_child)
                else: recon_model_recursive(module_child)

        recon_model_recursive(qnn)
        if args.act_quant and args.order == 'after': set_act_quantize_params(qnn, cali_data=cali_data, awq=False, order=args.order)
    else:
        set_act_quantize_params(qnn, cali_data=cali_data, awq=False, order=args.order)

    qnn.set_quant_state(weight_quant=True, act_quant=args.act_quant)
    return qnn
